-- of a sheet overlap (checked when one is added, with the sheet locked); a claim belongs to the
-- period whose dates contain its date, or to none.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(100) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CONSTRAINT period_from_to CHECK (from_date <= to_date),
    CONSTRAINT period_sheet_name UNIQUE (sheet_id, name)
);
-- A closed period: its due-total is fixed at the moment it was closed (closed_total), so later rate
-- changes leave it as it is, and no claim dated inside it can be added, edited or moved.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(14, 2);
-- The sheet's period numbering from: while it is set and the sheet's today is on or after it, a claim opened
-- is numbered within the period its date is in (<period name>-<n>), or X-<n> when in none. None means off.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;

-- A claim's number (and the number a correction names) is now text: a sheet-wide number (1, 2, ...) or a
-- number within a period (P1-1, X-1).
ALTER TABLE claim DROP CONSTRAINT claim_number_unique;
