package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Stream;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The figures of a sheet as the screen shows them: each person's claimed, due-total and overdue-total, and the
 * sheet's claimed-total, due-total and overdue-total. A change takes the figures before it and, once made, records
 * a ROLLUP line for each person whose figures moved and a TOTALS line when any of the sheet's totals moved.
 */
@Service
public class Rollup {

    /** A person's figures: claimed, due-total and overdue-total, each with two decimals; due-total is "n/a" when they
     *  have none. */
    public record PersonFigures(String name, String claimed, String dueTotal, String overdueTotal) {
    }

    /** A sheet's figures: each person's, by id in the order they were added, and the sheet's totals. */
    public record Figures(Map<Long, PersonFigures> people, String claimedTotal, String dueTotal, String overdueTotal) {
    }

    private static final String NOT_AVAILABLE = "n/a";

    private final SheetRepository sheets;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final Audit audit;

    public Rollup(SheetRepository sheets, PersonRepository people, ClaimRepository claims, RateRepository rates,
            Audit audit) {
        this.sheets = sheets;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.audit = audit;
    }

    /** The sheet's figures as the store holds them now. */
    public Figures of(String sheetId) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        List<Rate> sheetRates = rates.findBySheetId(sheetId);
        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
        Map<Long, PersonFigures> byPerson = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal overdueTotal = BigDecimal.ZERO.setScale(2);
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> counting = sheetClaims.stream()
                    .filter(c -> c.getPersonId().equals(person.getId()) && person.counts(c))
                    .toList();
            BigDecimal claimed = counting.stream().map(Claim::getAmount)
                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
            claimedTotal = claimedTotal.add(claimed);
            // As on screen: with no rate in force today for their grade on the sheet's today, nor for the grade
            // any of their claims is at, and no claim that has a due, the person has no due-total.
            List<BigDecimal> dues = counting.stream()
                    .map(c -> dueOf(c, ratesOf(sheetRates, person.gradeOn(c.getDate())), sheet, sheetClaims))
                    .filter(Objects::nonNull)
                    .toList();
            boolean anyRate = today != null && Stream.concat(Stream.of(person.gradeOn(today)),
                            counting.stream().map(c -> person.gradeOn(c.getDate())))
                    .anyMatch(grade -> Rate.inForceOn(ratesOf(sheetRates, grade), today).isPresent());
            String due = NOT_AVAILABLE;
            if (!dues.isEmpty() || anyRate) {
                BigDecimal sum = dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
                BigDecimal total = sheet == null ? sum : sheet.capped(sum);
                dueTotal = dueTotal.add(total);
                due = total.toPlainString();
            }
            // As on screen: the dues of the claims that count which are open and due by a day before the sheet's today.
            BigDecimal overdue = counting.stream()
                    .filter(c -> today != null && c.getStatus().isOpen() && c.getDueBy().isBefore(today))
                    .map(c -> dueOf(c, ratesOf(sheetRates, person.gradeOn(c.getDate())), sheet, sheetClaims))
                    .filter(Objects::nonNull)
                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
            overdueTotal = overdueTotal.add(overdue);
            byPerson.put(person.getId(),
                    new PersonFigures(person.getName(), claimed.toPlainString(), due, overdue.toPlainString()));
        }
        return new Figures(byPerson, claimedTotal.toPlainString(), dueTotal.toPlainString(),
                overdueTotal.toPlainString());
    }

    /** The due-total of the claims that count (a held person's open ones dated within a hold and not stated do not) dated from {@code from} to {@code to} inclusive, as the
     *  screen shows a period's: each claim's due, none counting as 0. */
    public BigDecimal dueTotalBetween(String sheetId, LocalDate from, LocalDate to) {
        List<Rate> sheetRates = rates.findBySheetId(sheetId);
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        Map<Long, Person> personOf = new LinkedHashMap<>();
        people.findBySheetIdOrderByIdAsc(sheetId).forEach(p -> personOf.put(p.getId(), p));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
        for (Claim claim : sheetClaims) {
            Person person = personOf.get(claim.getPersonId());
            if (person == null || !person.counts(claim) || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
                continue;
            }
            BigDecimal due = dueOf(claim, ratesOf(sheetRates, person.gradeOn(claim.getDate())), sheet, sheetClaims);
            if (due != null) {
                total = total.add(due);
            }
        }
        return total;
    }

    /**
     * Record, once the change commits, how the sheet's figures moved since {@code before}: a ROLLUP line
     * for each person whose figures changed (one who did not exist before counting as changed), then a
     * TOTALS line if the sheet's totals changed. Nothing is recorded when no figure moved.
     */
    public void recordChanges(String sheetId, String user, Figures before) {
        Figures after = of(sheetId);
        after.people().forEach((id, figures) -> {
            PersonFigures was = before.people().get(id);
            if (was == null || !was.claimed().equals(figures.claimed()) || !was.dueTotal().equals(figures.dueTotal())
                    || !was.overdueTotal().equals(figures.overdueTotal())) {
                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
                        + " claimed=" + figures.claimed() + " due-total=" + figures.dueTotal()
                        + " overdue-total=" + figures.overdueTotal());
            }
        });
        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
                || !before.overdueTotal().equals(after.overdueTotal())) {
            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
        }
    }

    /** The rates of one grade among a sheet's. */
    private static List<Rate> ratesOf(List<Rate> sheetRates, String grade) {
        return sheetRates.stream().filter(r -> r.getGrade().equals(grade)).toList();
    }

    /** A claim's due: its settled figure, else its stated one (none while PENDING), else its amount at the rate in force on its date of
     *  its person's grade in force on that date, rounded as the claim rounds (by the sheet's policy date), raised to the sheet's floor unless it is a correction; an overdue claim's late charge is added on top of the figure. */
    private static BigDecimal dueOf(Claim claim, List<Rate> gradeRates, Sheet sheet, List<Claim> sheetClaims) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        BigDecimal floor = sheet == null ? null : sheet.getFloor();
        RoundingMode rounding = sheet == null ? RoundingMode.HALF_EVEN
                : sheet.roundingFor(ClaimService.roundingDate(claim, sheetClaims));
        BigDecimal figure = claim.isBound() ? claim.getBoundDue()
                : Rate.inForceOn(gradeRates, claim.getDate())
                        .map(rate -> ClaimService.liveFigure(claim, rate.getRate(), floor, rounding))
                        .orElse(null);
        return figure == null || sheet == null ? figure : figure.add(ClaimService.lateCharge(claim, figure, sheet));
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';

export interface PeriodView {
  id: number;
  /** Unique on its sheet. */
  name: string;
  /** The first day of the period (yyyy-mm-dd), inclusive. */
  from: string;
  /** The last day of the period (yyyy-mm-dd), inclusive. */
  to: string;
  /** Whether the period is closed: no claim dated inside it can be added, edited or moved. */
  closed: boolean;
  /** The due-total fixed when the period was closed, with exactly two decimals; null while open. */
  closedTotal: string | null;
}

/** A period as the form submits it: a blank from-date takes the sheet's today. */
export interface PeriodForm {
  name: string;
  from: string | null;
  to: string;
}

/** The period whose dates contain a date (yyyy-mm-dd); undefined when none does. */
export function periodOn(periods: readonly PeriodView[], date: string): PeriodView | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

// The periods of the active sheet, by from-date; no two of them overlap.
@Injectable({ providedIn: 'root' })
export class Periods {
  private readonly http = inject(HttpClient);
  private readonly periods = signal<PeriodView[]>([]);
  readonly list = this.periods.asReadonly();

  /** Re-read a sheet's periods from the store; null clears them. */
  load(sheetId: string | null): Observable<PeriodView[]> | null {
    this.periods.set([]);
    if (sheetId === null) return null;
    return this.http.get<PeriodView[]>(this.base(sheetId)).pipe(tap((periods) => this.periods.set(periods)));
  }

  /** Add a period; refused when its name is in use, it ends before it starts, or it overlaps another. */
  add(sheetId: string, period: PeriodForm): Observable<PeriodView> {
    return this.http
      .post<PeriodView>(this.base(sheetId), period)
      .pipe(tap((saved) => this.periods.update((list) => [...list, saved].sort((a, b) => (a.from < b.from ? -1 : 1)))));
  }

  /** Close a period, fixing its due-total; refused when it is already closed. */
  close(sheetId: string, name: string): Observable<PeriodView> {
    return this.http
      .post<PeriodView>(`${this.base(sheetId)}/${encodeURIComponent(name)}/close`, {})
      .pipe(tap((saved) => this.periods.update((list) => list.map((p) => (p.id === saved.id ? saved : p)))));
  }

  /** Reopen a closed period, making its due-total live again; only a steward may. */
  reopen(sheetId: string, name: string): Observable<PeriodView> {
    return this.http
      .post<PeriodView>(`${this.base(sheetId)}/${encodeURIComponent(name)}/reopen`, {})
      .pipe(tap((saved) => this.periods.update((list) => list.map((p) => (p.id === saved.id ? saved : p)))));
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/periods`;
  }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, inject, input, signal } from '@angular/core';
import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { EMPTY, switchMap } from 'rxjs';
import { PeriodView, Periods } from '../../core/periods';
import { Sheets } from '../../core/sheet';

// The sheet's periods, each with its due-total, and a form to add one.
@Component({
  selector: 'app-periods',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="periods-heading">
      <h2 id="periods-heading">Periods</h2>
      <ul aria-label="Periods of the sheet">
        @for (p of periods.list(); track p.id) {
          <li [attr.data-testid]="'period-row-' + p.name">
            <span data-testid="period-name">{{ p.name }}</span>
            from <span data-testid="period-from">{{ p.from }}</span>
            to <span data-testid="period-to">{{ p.to }}</span>
            — due <span data-testid="period-due-total">{{ dueTotals().get(p.id) ?? '0.00' }}</span>
            — closed <span data-testid="period-closed">{{ p.closed ? 'yes' : 'no' }}</span>
            <button type="button" data-testid="period-close" (click)="close(p)" [disabled]="closing() === p.id"
                    [attr.aria-label]="'Close period ' + p.name">Close</button>
            <button type="button" data-testid="period-reopen" (click)="reopen(p)" [disabled]="closing() === p.id"
                    [attr.aria-label]="'Reopen period ' + p.name">Reopen</button>
            @if (periodError()?.id === p.id) {
              <p role="alert" data-testid="period-error">{{ periodError()?.message }}</p>
            }
          </li>
        }
      </ul>

      <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Add a period">
        <label for="period-form-name">Name</label>
        <input id="period-form-name" data-testid="period-form-name" formControlName="name" autocomplete="off" />
        <label for="period-form-from">From (blank: today)</label>
        <input id="period-form-from" type="date" data-testid="period-form-from" formControlName="from" />
        <label for="period-form-to">To</label>
        <input id="period-form-to" type="date" data-testid="period-form-to" formControlName="to" />
        <button type="submit" data-testid="period-form-submit" [disabled]="saving()">Add period</button>
        @if (error(); as err) {
          <p role="alert" data-testid="period-form-error">{{ err }}</p>
        }
      </form>
    </section>
  `,
})
export class PeriodsPanel {
  private readonly sheets = inject(Sheets);
  protected readonly periods = inject(Periods);

  /** Each period's due-total, with two decimals, by period id. */
  readonly dueTotals = input.required<ReadonlyMap<number, string>>();

  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);
  /** The period being closed or reopened, so a second press waits for the first. */
  protected readonly closing = signal<number | null>(null);
  /** The error of the last action taken on a period's row, until the next action on that row. */
  protected readonly periodError = signal<{ id: number; message: string } | null>(null);

  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
    from: new FormControl('', { nonNullable: true }),
    to: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    // Each (re)load of a sheet re-reads its periods from the store.
    toObservable(this.sheets.loaded)
      .pipe(
        switchMap((sheet) => {
          this.error.set(null);
          this.periodError.set(null);
          return this.periods.load(sheet?.id ?? null) ?? EMPTY;
        }),
        takeUntilDestroyed(),
      )
      .subscribe({ error: () => this.error.set('Could not read the periods.') });
    // An error is removed as soon as its form is changed.
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
  }

  protected close(p: PeriodView): void {
    if (this.closing() === p.id) return;
    this.periodError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    this.closing.set(p.id);
    this.periods.close(sheet.id, p.name).subscribe({
      next: () => this.closing.set(null),
      error: (err: unknown) => {
        this.closing.set(null);
        this.periodError.set({
          id: p.id,
          message: err instanceof HttpErrorResponse && err.status === 409
            ? 'That period is already closed.'
            : 'Could not close that period.',
        });
      },
    });
  }

  protected reopen(p: PeriodView): void {
    if (this.closing() === p.id) return;
    this.periodError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    this.closing.set(p.id);
    this.periods.reopen(sheet.id, p.name).subscribe({
      next: () => this.closing.set(null),
      error: (err: unknown) => {
        this.closing.set(null);
        const status = err instanceof HttpErrorResponse ? err.status : 0;
        this.periodError.set({
          id: p.id,
          message: status === 403
            ? 'Only a steward can reopen a period.'
            : status === 409
              ? 'That period is not closed.'
              : 'Could not reopen that period.',
        });
      },
    });
  }

  protected submit(): void {
    // A second submit before the first has answered is ignored, so it stores one record.
    if (this.saving()) return;
    this.error.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const value = this.form.getRawValue();
    const name = value.name.trim();
    const from = value.from.trim();
    const to = value.to.trim();
    if (name === '') {
      this.error.set('Type a name for the period.');
      return;
    }
    if (from !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(from)) {
      this.error.set('Choose a from-date, or leave it blank for today.');
      return;
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(to)) {
      this.error.set('Choose a to-date for the period.');
      return;
    }
    if (to < (from === '' ? sheet.today : from)) {
      this.error.set('A period cannot end before it starts.');
      return;
    }
    this.saving.set(true);
    this.periods.add(sheet.id, { name, from: from === '' ? null : from, to }).subscribe({
      next: () => {
        this.saving.set(false);
        this.form.reset({ name: '', from: '', to: '' }, { emitEvent: false });
      },
      error: (err: unknown) => {
        this.saving.set(false);
        this.error.set(
          err instanceof HttpErrorResponse && err.status === 409
            ? 'That period’s name is in use, or it overlaps another period.'
            : 'Could not add that period.',
        );
      },
    });
  }
}
import { Component, input } from '@angular/core';
import { Grade } from '../../core/people';

/** A grade's line: how many people not retired are on it today, and their due-totals added up. */
export interface GradeSummary {
  grade: Grade;
  count: number;
  dueTotal: string;
}

/** A period's line: its due-total, as the period's row shows it. */
export interface PeriodSummary {
  name: string;
  dueTotal: string;
}

/** A status's line: how many claims on the sheet are in it. */
export interface StatusSummary {
  status: string;
  count: number;
}

// The sheet's figures at a glance, per grade, per period and per claim status; each agrees with the list.
@Component({
  selector: 'app-summary',
  template: `
    <section aria-labelledby="summary-heading">
      <h2 id="summary-heading">Summary</h2>
      <ul aria-label="By grade">
        @for (g of grades(); track g.grade) {
          <li>Grade {{ g.grade }}:
            <span [attr.data-testid]="'summary-grade-' + g.grade + '-count'">{{ g.count }}</span> people, due
            <span [attr.data-testid]="'summary-grade-' + g.grade + '-due-total'">{{ g.dueTotal }}</span></li>
        }
      </ul>
      <ul aria-label="By period">
        @for (p of periods(); track p.name) {
          <li>Period {{ p.name }}: due
            <span [attr.data-testid]="'summary-period-' + p.name + '-due-total'">{{ p.dueTotal }}</span></li>
        }
      </ul>
      <ul aria-label="By status">
        @for (s of statuses(); track s.status) {
          <li>{{ s.status }}:
            <span [attr.data-testid]="'summary-status-' + s.status + '-count'">{{ s.count }}</span> claims</li>
        }
      </ul>
    </section>
  `,
})
export class SummaryPanel {
  readonly grades = input.required<readonly GradeSummary[]>();
  readonly periods = input.required<readonly PeriodSummary[]>();
  readonly statuses = input.required<readonly StatusSummary[]>();
}

